import pytest
from hypothesis import example, given, strategies as st

from ledger.billing.refund import refund


@pytest.mark.invariant("cents_conserved")
@given(
    total_cents=st.integers(min_value=-10**7, max_value=0),
    weights=st.lists(st.integers(min_value=1, max_value=1_000), min_size=1, max_size=8),
)
@example(total_cents=-100, weights=[1, 2])
def test_refund_conserves_cents(total_cents, weights):
    shares = refund(total_cents, weights)
    assert sum(shares) == total_cents
    assert all(share <= 0 for share in shares)
